def sec(id, title, intro, items):
    S.append(dict(id=id, title=title, intro=intro, items=items))


def q(id, q_, ctx, opts, rec, multi=False):
    return dict(id=id, q=q_, ctx=ctx, opts=[list(o) for o in opts], rec=rec, multi=multi)


